        elif is_bd(d, hol):
            tag += 'business day, allowed'
        else:
            nb = next_bd(d, hol)
            tag += ('Freya Bank holiday' if d in hol else 'weekend') + ', not allowed; offer the next business day ' + sp(nb) + ' (' + nb.isoformat() + ')'
        rows.append(tag)
        d = d + datetime.timedelta(days=1)
    wk = []
    mon = week_monday(today)
    for i, name in enumerate(WEEKDAYS):
        this_d = mon + datetime.timedelta(days=i)
        next_d = this_d + datetime.timedelta(days=7)
        this_txt = sp(this_d) if this_d >= today else 'already past'
        wk.append('this ' + name.title() + ' = ' + this_txt + '; next ' + name.title() + ' = ' + sp(next_d))
    a1_amount = money(past_due) + ' (or the floor ' + money(floor) + ' if the customer already said the full amount is too much)'
    lines = [
        'Today is ' + sp(today) + ' (' + today.isoformat() + '), time ' + now.strftime('%H:%M') + '.',
        'Product: ' + label + '. days late: ' + str(days) + ' (' + band + ' band).',
        'Full past-due amount: ' + money(past_due) + '. Floor (the lowest amount you may record): ' + money(floor) + '.',
        'Accept any amount from ' + money(floor) + ' to ' + money(past_due) + ', both included. Below ' + money(floor) + ' cannot be recorded. More than ' + money(past_due) + ' cannot be recorded.',
        'Deadline (latest promise date): ' + sp(deadline) + ' (' + deadline.isoformat() + '). Earliest date: today ' + ('(' + today.isoformat() + ')' if is_bd(today, hol) else 'is not a business day, so ' + sp(next_bd(today, hol))) + '.',
